toggle.bootpaint=function()
    local state=toggle.bootpanel;if not state or state.closed then return end
    local now=tick();local dt=math.max(0,math.min(0.1,now-(state.lastpaint or now-1/60)));state.lastpaint=now
    if state.finished then state.phase=math.max(0,state.phase-dt/0.20)end
    if state.finished and state.phase<=0 then toggle.bootcleanup();return end
    local viewport=ws.CurrentCamera and ws.CurrentCamera.ViewportSize or cam.ViewportSize;local w=math.min(300,math.max(160,viewport.X-32));local h=84;local x=math.floor((viewport.X-w)/2);local y=math.floor((viewport.Y-h)/2);local a=state.phase
    state.bg.Position=Vector2.new(x,y);state.bg.Size=Vector2.new(w,h);state.bg.Transparency=0.98*a;state.bg.Visible=a>0
    state.border.Position=state.bg.Position;state.border.Size=state.bg.Size;state.border.Transparency=0.26*a;state.border.Visible=a>0
    local logow=math.min(w-32,(h-20)*367/158);local logoh=logow*158/367
    state.logo.Position=Vector2.new(x+(w-logow)/2,y+(h-logoh)/2);state.logo.Size=Vector2.new(logow,logoh);state.logo.Transparency=a;state.logo.Visible=a>0
