local function dropdownvalues()
    if dropdownkind=="rosterview"then return {"List","Grid"}elseif dropdownkind=="playerbackpack"or dropdownkind=="crateinventorystyle"then return {"Image","Text"}elseif dropdownkind=="oofelements"then return {"Icon","Name","Distance"}elseif dropdownkind=="oof"then return toggle.extra.order elseif dropdownkind=="safespotelements"then return {"Label","Distance"}elseif dropdownkind=="espicons"then return toggle.espiconorder
    elseif dropdownkind=="fonttarget"then return toggle.fonttargetnames
    elseif dropdownkind=="fontfamily"then return fontnames
    elseif dropdownkind=="watermarkelements"then return toggle.watermarkorder
    elseif dropdownkind=="crateelements"or dropdownkind=="flareelements"or dropdownkind=="trapelements"or dropdownkind=="locationelements"then return {"icons"}
    elseif dropdownkind=="terraineditor"then return {"grass","wind","water"}elseif dropdownkind=="posteditor"then return toggle.posteffectnames
    elseif dropdownkind=="scrapedit"then local values={};for i=1,#toggle.scraporder do values[i]=toggle.scraporder[i].label end;return values
    elseif dropdownkind=="locationedit"then local values={};for i=1,#toggle.locationorder do values[i]=toggle.locationorder[i].label end;return values
    elseif dropdownkind=="panelstyle"or dropdownkind=="hudstyle"or dropdownkind=="espstyle"or dropdownkind=="playerstyle"or dropdownkind=="rakestyle"then return {"modern","compact"}
    elseif dropdownkind=="hudelements"then local values={};for _,entry in ipairs(toggle.hudselectionorder)do values[#values+1]=entry.label end;return values
    elseif dropdownkind=="rakeelements"then return toggle.espelementorder.rake
    elseif dropdownkind=="playerelements"then return toggle.espelementorder.players
    elseif dropdownkind=="espfont"or dropdownkind=="hudfont"then return fontnames
    elseif dropdownkind=="preset"then return toggle.presetorder
    elseif dropdownkind=="distanceposition"then return {"below","above"}
    elseif dropdownkind=="scrapstyle"then return {"tiers","points"}
    elseif dropdownkind=="scrapteleport"then return {"nearest","value","random","nearest to cursor"}
    elseif dropdownkind=="ringshape"then return {"circle","square","triangle","hexagon"}
    elseif dropdownkind=="rgbdirection"then return {"left","right"}
    elseif dropdownkind=="containergrouping"then return {"stacked","ungrouped"}
    elseif dropdownkind=="containerorientation"then return {"horizontal","vertical"}
    elseif dropdownkind=="containerstyle"then return {"modern","compact"}
    elseif dropdownkind=="poweractivitymode"then return {"activity","always"}
    elseif dropdownkind=="notificationstyle"then return {"modern","compact"}
    elseif dropdownkind=="notificationposition"then return {"bottom left","bottom right","middle left","middle right"}
    elseif dropdownkind=="tracers"then return toggle.tracers.order
    elseif dropdownkind=="notificationtypes"then return toggle.notifyorder
    elseif dropdownkind=="worldstats"then local values={};for i=1,#toggle.worldorder do values[i]=toggle.worldorder[i].label end;return values
    elseif dropdownkind=="autocollect"then local values={};for i=1,#toggle.autocollect.order do values[i]=toggle.autocollect.order[i].label end;return values
    elseif dropdownkind=="prompts"then local values={};for i=1,#toggle.promptoptionorder do values[i]=toggle.promptoptionorder[i].label end;return values
    elseif dropdownkind=="accentbars"then local values={};for i=1,#toggle.accentbarorder do values[i]=toggle.accentbarorder[i].label end;return values
    elseif dropdownkind=="resets"then local values={};for i=1,#toggle.resetorder do values[i]=toggle.resetorder[i].label end;return values
    elseif dropdownkind=="playeritems"then return toggle.playeresp.names
    elseif dropdownkind=="shopitem"or dropdownkind=="autobuyitems"or dropdownkind=="autosellitems"then toggle.refreshshop(false);return toggle.shop.names
    elseif dropdownkind=="config"then return configslots end
    return {}
end
toggle.presetpreviewcache={};toggle.presetpreviews={}
toggle.presetpreviewassets={"","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","","",""}
toggle.presetpreviewdata=function(index)
    local cached=toggle.presetpreviewcache[index];if cached then return cached end
    local source=toggle.presetpreviewassets[index];if not source then
        local theme=themes[index];if not theme or not theme.custom then return nil end
        local rows={};for y=0,27 do local row={string.char(0)};for x=0,95 do local c=toggle.colormix(theme.accent,theme.bg,x/95);local dx=math.max(7-(x+0.5),0,x+0.5-89);local dy=math.max(7-(y+0.5),0,y+0.5-21);local alpha=math.floor(clamp(7.5-math.sqrt(dx*dx+dy*dy),0,1)*255+0.5);row[#row+1]=string.char(channel(c.R),channel(c.G),channel(c.B),alpha)end;rows[#rows+1]=table.concat(row)end
        cached=toggle.iconpng(96,28,table.concat(rows));toggle.presetpreviewcache[index]=cached;return cached
    end
    cached=toggle.iconbase64(source);toggle.presetpreviewcache[index]=cached;return cached
end

toggle.hidepresetpreviews=function()for slot,entry in pairs(toggle.presetpreviews)do if slot~="selected"then toggle.setvisible(entry.image,false)end end end
toggle.paintpresetpreview=function(slot,index,x,y,w,h,alpha,on)
    local entry=toggle.presetpreviews[slot];if not on then if entry then toggle.setvisible(entry.image,false)end;return end
    if not entry then entry={image=toggle.newicon(slot=="selected"and 121 or 204)};toggle.presetpreviews[slot]=entry end
    if entry.index~=index then local data=toggle.presetpreviewdata(index);if not data then toggle.setvisible(entry.image,false);entry.index=nil;return end;toggle.setprop(entry.image,"Data",data);entry.index=index end
    toggle.setpos(entry.image,x,y);toggle.setprop(entry.image,"Size",Vector2.new(w,h));toggle.setprop(entry.image,"Transparency",alpha);toggle.setvisible(entry.image,true)
end
toggle.menufieldcolor=function(surface)
    surface=surface or toggle.colormix(color("bg"),color("text"),toggle.visualstyle=="compact"and 0.035 or toggle.textbrightness(color("bg"))>0.58 and 0.025 or 0.035)
    return toggle.colormix(surface,toggle.white,0.02)
end
toggle.dropdownitemcolor=function(hover,selected)
    local panel=toggle.menufieldcolor();local base=toggle.colormix(panel,toggle.white,0.012+hover*0.018)
    local tint=toggle.colormix(base,color("accent"),selected*0.10)
    return Color3.new(math.max(base.R,tint.R),math.max(base.G,tint.G),math.max(base.B,tint.B))
end
toggle.dropdownitemkey=function(kind,value)
    if kind=="playeritems"then local item=toggle.multientry(toggle.playeresp.order,value);return item and item.name end
    if kind=="autocollect"then return toggle.autocollectname(value)end
    if kind=="autobuyitems"or kind=="autosellitems"or kind=="shopitem"then local item=toggle.shop.lookup[value];return item and item.name end
end
toggle.dropdownpictures={}
