toggle.worlddepthsort=function(a,b)
    local ad,bd=math.floor((a.lastmeters or math.huge)*2),math.floor((b.lastmeters or math.huge)*2)
    if ad~=bd then return ad>bd end;return(a.depthid or 0)<(b.depthid or 0)
